import { path } from '@servicenow/sdk-build-core'
import { findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from './test-utils'
import { createTestContext } from '../../test-utils'

describe('Scheduled Trigger Types Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Daily scheduled trigger', () => {
        test('Daily scheduled trigger instance maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'daily-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('time')).toBe('1970-01-01 08:30:00')
        })

        test('Daily scheduled trigger with mandatory fields only (DEF0777644)', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'daily-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            // Find the mandatory-only trigger (second flow in the file)
            const trgInst = merged['sys_hub_trigger_instance_v2'][1]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value
            //const expectedTime = getUtcTime(9, 0, 0)
            expect(val('time')).toBe('1970-01-01 09:00:00')
        })
    })

    describe('Weekly scheduled trigger', () => {
        test('Weekly scheduled trigger instance maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'weekly-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('day_of_week')).toBe('2')
            //const expectedTime = getUtcTime(9, 0, 0)
            expect(val('time')).toBe('1970-01-01 09:00:00')
        })
    })

    describe('Monthly scheduled trigger', () => {
        test('Monthly scheduled trigger instance maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'monthly-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('day_of_month')).toBe(1)
            //const expectedTime = getUtcTime(11, 11, 11)
            expect(val('time')).toBe('1970-01-01 11:11:11')
        })
    })

    describe('Repeat scheduled trigger', () => {
        test('Repeat scheduled trigger instance maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'repeat-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('repeat')).toBe('1970-01-12 11:11:11')
        })

        test('Repeat scheduled trigger with time parameter', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'repeat-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            // Find the repeat trigger with time (second flow in the file)
            const trgInst = merged['sys_hub_trigger_instance_v2'][1]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Repeat triggers with time parameter still only serialize the repeat duration
            expect(val('repeat')).toBe('1970-01-12 11:11:11')
            // Note: time parameter is not serialized in repeat trigger inputs
        })
    })

    describe('Run-once scheduled trigger', () => {
        test('Run-once scheduled trigger instance maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'run-once-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('run_in')).toBe('2025-12-31 23:59:00')
        })
    })

    // =============================================================================
    // Bi-Directional Tests: Fluent → XML → Fluent
    // =============================================================================

    describe('Scheduled Triggers - Fluent to XML', () => {
        test('Daily trigger generates correct XML with time parameter', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'daily-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('daily')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify time parameter is serialized
            expect(val('time')).toBe('1970-01-01 08:30:00')
        })

        test('Weekly trigger generates correct XML with day_of_week', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'weekly-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('weekly')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify day_of_week and time are serialized
            expect(val('day_of_week')).toBe('2')
            //const expectedTime = getUtcTime(9, 0, 0)
            expect(val('time')).toBe('1970-01-01 09:00:00')
        })

        test('Monthly trigger generates correct XML with day_of_month', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'monthly-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('monthly')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify day_of_month and time are serialized
            expect(val('day_of_month')).toBe(1)
        })

        test('Repeat trigger generates correct XML with repeat duration', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'repeat-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('repeat')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify repeat duration is serialized
            expect(val('repeat')).toBe('1970-01-12 11:11:11')
        })

        test('Run-once trigger generates correct XML with run_in parameter', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'run-once-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('run_once')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify run_in parameter is serialized
            expect(val('run_in')).toBe('2025-12-31 23:59:00')
        })
    })

    describe('Scheduled Triggers - XML to Fluent', () => {
        test('Daily trigger XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            // Use the existing Fluent file for precise validation
            const merged = await getMergedRecordUpdates(project, 'daily-trigger.now.ts', 'oob-triggers/fluent')

            // Get the first flow
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type
            expect(trgInst.trigger_type).toBe('daily')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify time parameter with precise value
            expect(val('time')).toBe('1970-01-01 08:30:00')
        })

        test('Weekly trigger XML transforms with day_of_week', async () => {
            const project = ctx.createProject()

            // Use the existing Fluent file for precise validation
            const merged = await getMergedRecordUpdates(project, 'weekly-trigger.now.ts', 'oob-triggers/fluent')

            // Get the first flow
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type
            expect(trgInst.trigger_type).toBe('weekly')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify day_of_week and time parameters with precise values
            expect(val('day_of_week')).toBe('2') // Monday
            //const expectedTime = getUtcTime(9, 0, 0)
            expect(val('time')).toBe('1970-01-01 09:00:00')
        })

        test('Monthly trigger XML transforms with day_of_month', async () => {
            const project = ctx.createProject()

            // Use the existing Fluent file for precise validation
            const merged = await getMergedRecordUpdates(project, 'monthly-trigger.now.ts', 'oob-triggers/fluent')

            // Get the first flow
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type
            expect(trgInst.trigger_type).toBe('monthly')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify day_of_month and time parameters with precise values
            expect(val('day_of_month')).toBe(1)
            expect(val('time')).toBe('1970-01-01 11:11:11')
        })

        test('Repeat trigger XML transforms with Duration helper', async () => {
            const project = ctx.createProject()

            // Use the existing Fluent file for precise validation
            const merged = await getMergedRecordUpdates(project, 'repeat-trigger.now.ts', 'oob-triggers/fluent')

            // Get the first flow
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type
            expect(trgInst.trigger_type).toBe('repeat')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify repeat parameter with precise value
            expect(val('repeat')).toBe('1970-01-12 11:11:11')
        })

        test('Run-once trigger XML transforms with run_in parameter', async () => {
            const project = ctx.createProject()

            // Use the existing Fluent file for precise validation
            const merged = await getMergedRecordUpdates(project, 'run-once-trigger.now.ts', 'oob-triggers/fluent')

            // Get the first flow
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type
            expect(trgInst.trigger_type).toBe('run_once')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify run_in parameter with precise value
            expect(val('run_in')).toBe('2025-12-31 23:59:00')
        })

        test('Generated Fluent code has correct trigger outputs', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Daily_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Daily_Trigger.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify trigger outputs are accessible
            expect(content).toContain('_params.trigger')
            expect(content).toContain('_params.trigger.run_start_time')
            expect(content).toContain('_params.trigger.run_start_date_time')

            // Verify correct data types are used for data pills
            expect(content).toContain("wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')")
            expect(content).toContain("wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')")

            // Verify action exists
            expect(content).toContain('wfa.action(')
            expect(content).toContain('action.core.log')
        })

        test('Repeat trigger XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Repeat_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Repeat_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('Test_Repeat_Trigger.now.ts')

            const content = changedFiles[0].getContent()

            // Verify trigger type
            expect(content).toContain('trigger.scheduled.repeat')
            expect(content).toContain('wfa.trigger(')

            // Verify Duration helper is used for repeat parameter
            expect(content).toContain('Duration(')
            expect(content).toContain('days:')
            expect(content).toContain('hours:')
            expect(content).toContain('minutes:')
            expect(content).toContain('seconds:')

            // Verify trigger outputs are accessible
            expect(content).toContain('_params.trigger.run_start_time')
            expect(content).toContain('_params.trigger.run_start_date_time')
        })

        test('Repeat trigger with all parameters XML transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Repeat_Trigger_All_Params.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Repeat_Trigger_All_Params.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type
            expect(content).toContain('trigger.scheduled.repeat')

            // Verify Duration helper with all parameters
            expect(content).toContain('Duration(')

            // Verify time parameter if present
            expect(content).toMatch(/time:|Duration\(/)
        })

        test('Weekly trigger XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Weekly_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Weekly_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('Test_Weekly_Trigger.now.ts')

            const content = changedFiles[0].getContent()

            // Verify trigger type
            expect(content).toContain('trigger.scheduled.weekly')
            expect(content).toContain('wfa.trigger(')

            // Verify day_of_week parameter
            expect(content).toContain('day_of_week:')

            // Verify Time helper is used
            expect(content).toContain('time: Time(')
            expect(content).toContain('hours:')

            // Verify trigger outputs are accessible
            expect(content).toContain('_params.trigger.run_start_time')
            expect(content).toContain('_params.trigger.run_start_date_time')
        })

        test('Monthly trigger XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Monthly_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Monthly_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('Test_Monthly_Trigger.now.ts')

            const content = changedFiles[0].getContent()

            // Verify trigger type
            expect(content).toContain('trigger.scheduled.monthly')
            expect(content).toContain('wfa.trigger(')

            // Verify day_of_month parameter
            expect(content).toContain('day_of_month:')

            // Verify Time helper is used
            expect(content).toContain('time: Time(')
            expect(content).toContain('hours:')
            expect(content).toContain('minutes:')

            // Verify trigger outputs are accessible
            expect(content).toContain('_params.trigger.run_start_time')
            expect(content).toContain('_params.trigger.run_start_date_time')
        })

        test('Run-once trigger XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Run_Once_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Run_Once_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('Test_Run_Once_Trigger.now.ts')

            const content = changedFiles[0].getContent()

            // Verify trigger type
            expect(content).toContain('trigger.scheduled.runOnce')
            expect(content).toContain('wfa.trigger(')

            // Verify run_in parameter (uses string value directly, not DateTime helper)
            expect(content).toContain('run_in:')
            expect(content).toMatch(/run_in:\s*['"][\d\-:\s]+['"]/)

            // Verify trigger outputs are accessible
            expect(content).toContain('_params.trigger.run_start_time')
            expect(content).toContain('_params.trigger.run_start_date_time')
        })
    })

    describe('Scheduled Triggers - Round Trip', () => {
        test('Daily trigger: Fluent → XML preserves time configuration', async () => {
            const project = ctx.createProject()

            const merged = await getMergedRecordUpdates(project, 'daily-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('daily')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify time is preserved
            expect(val('time')).toBeDefined()
        })

        test('Weekly trigger: Fluent → XML preserves day_of_week and time', async () => {
            const project = ctx.createProject()

            const merged = await getMergedRecordUpdates(project, 'weekly-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify both parameters are preserved
            expect(val('day_of_week')).toBe('2')
            expect(val('time')).toBeDefined()
        })

        test('Repeat trigger: Fluent → XML preserves repeat duration', async () => {
            const project = ctx.createProject()

            const merged = await getMergedRecordUpdates(project, 'repeat-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify repeat duration is preserved
            expect(val('repeat')).toBe('1970-01-12 11:11:11')
        })

        test('All scheduled triggers have correct trigger_type', async () => {
            const project = ctx.createProject()

            // Test daily
            const dailyMerged = await getMergedRecordUpdates(project, 'daily-trigger.now.ts', 'oob-triggers/fluent')
            expect(dailyMerged['sys_hub_trigger_instance_v2'][0].trigger_type).toBe('daily')

            // Test weekly
            const weeklyMerged = await getMergedRecordUpdates(project, 'weekly-trigger.now.ts', 'oob-triggers/fluent')
            expect(weeklyMerged['sys_hub_trigger_instance_v2'][0].trigger_type).toBe('weekly')

            // Test monthly
            const monthlyMerged = await getMergedRecordUpdates(project, 'monthly-trigger.now.ts', 'oob-triggers/fluent')
            expect(monthlyMerged['sys_hub_trigger_instance_v2'][0].trigger_type).toBe('monthly')
        })
    })
})
